#!/usr/bin/env bash

BRANCH=$(git symbolic-ref --short HEAD)
GIT_COMMIT_ID=${GIT_COMMIT:-$(git rev-parse HEAD)}
BUILD_TIME=$(date +"%Y-%m-%dT%H:%M:%S%z")
BUILD_INFO_FILE=internal/buildinfo/data.go

cat <<EOF2 > ${BUILD_INFO_FILE}
// Code generated by generate-build-info.sh; DO NOT EDIT.

package buildinfo

// Data is returned by GET /build-info.
var Data = Info{
	Branch:    "${BRANCH}",
	Version:   "${GIT_COMMIT_ID}",
	BuildTime: "${BUILD_TIME}",
}
EOF2
echo "Wrote ${BUILD_INFO_FILE}"
cat ${BUILD_INFO_FILE}
